```cpp
#include <iostream>
#include <fstream>
#include <filesystem>
#include <vector>
#include <string>
#include <algorithm>
#include <cryptopp/keccak.h>
#include <cryptopp/hex.h>
#include <cryptopp/files.h>

namespace fs = std::filesystem;

// Guarda as informações de um arquivo coletado durante a varredura
struct Arquivo {
    std::string caminhoCompleto;   // ex.: "D:\Jogos\game.dll"
    std::string nomeArquivo;       // ex.: "game.dll"
    std::string hash512;           // hash Keccak-512 calculado
    bool selecionado = false;      // true quando o usuário escolher este arquivo
};

// Calcula o hash Keccak-512 (mesma lógica do código original)
std::string calcularKeccak512(const std::string& caminho) {
    CryptoPP::Keccak_512 hash;
    std::string digest;

    CryptoPP::FileSource(caminho.c_str(), true,
        new CryptoPP::HashFilter(hash,
            new CryptoPP::HexEncoder(
                new CryptoPP::StringSink(digest), true)));

    return digest;
}

// Ordena a lista pelo nome do arquivo (apenas para organizar a exibição)
bool porNome(const Arquivo& a, const Arquivo& b) {
    return a.nomeArquivo < b.nomeArquivo;
}

// Lê um número válido do teclado, com feedback em caso de erro de digitação
int pedirOpcaoValido(int minimo, int maxima) {
    int n;
    while (!(std::cin >> n)) {                           // entrou letra/espaços
        std::clearlin(std::cin);
        std::cout << "Digite apenas números (ex.: \"1\", \"0\")\n";
    }
    while (n < minimo || n > maxima) {                  // fora do intervalo
        std::clearlin(std::cin);
        std::cout << "Fora do intervalo. Use de 1 a " << maxima
                  << " ou 0. Nova tentativa: \n";
    }
    std::cin.ignore();                                  // remove a quebra de linha
    return n;
}

int main(int argc, char* argv[]) {
    // --------------------------
    // (Opcional) especificar a pasta
    // Ex.: ./programa "D:/alvos"
    // --------------------------
    std::string pastaTrabalho = fs::current_path().string();
    if (argc > 1) {
        try {
            pastaTrabalho = fs::absolute(fs::path(argv[1]).parent_path()).string();
        } catch (...) {
            // caminho indicado não existe ainda; continuamos na pasta atual
        }
    }

    // ========================
    // VARREDURA: procura .exe/.dll/.asi
    // ========================
    std::vector<Arquivo> arquivos;
    for (const auto& entrada : fs::directory_iterator(pastaTrabalho)) {
        if (!entrada.is_regular_file()) continue;

        std::string extensao = entrada.path().extension().string();
        if (extensao != ".exe" && extensao != ".dll" && extensao != ".asi") continue;

        std::string hash = calcularKeccak512(entrada.path().string());
        Arquivo a;
        a.caminhoCompleto = entrada.path().string();
        a.nomeArquivo    = entrada.path().filename().string();
        a.hash512        = hash;
        arquivos.push_back(std::move(a));
    }

    if (arquivos.empty()) {
        std::cerr << "Nenhum arquivo .exe/.dll/.asi encontrado em \""
                   << pastaTrabalho << "\".\n";
        return 0;
    }

    std::sort(arquivos.begin(), arquivos.end(), porNome);

    // ===========================================================
    // ETAPA 1 — gera rTalesHash.txt com os hashes de TODOS
    // (antes o arquivo saía como "rTales.ini")
    // ===========================================================
    {
        std::ofstream hashFile("rTalesHash.txt");
        for (const auto& a : arquivos) {
            hashFile << "\"" << a.nomeArquivo << "\" : " << a.hash512 << "\n";
        }
        hashFile.close();

        std::cout << "[1/3] Arquivo \"rTalesHash.txt\" gerado com "
                  << arquivos.size() << " arquivo(s).\n\n";
    }

    // ===========================================================
    // ETAPA 2 — lista no console para você escolher manualmente
    // ===========================================================
    int total = static_cast<int>(arquivos.size());

    std::cout << "===== Selecione manualmente os arquivos =====\n";
    std::cout << "Digite o número da linha (de 1 a " << total << ")\n";
    std::cout << "ou 0 para NÂO incluir nenhum arquivo no rTales.ini.\n\n";

    for (size_t i = 0; i < arquivos.size(); ++i) {
        const auto& h = arquivos[i].hash512;
        int mostrador = 36; // trechinho do hash para não poluir a tela
        std::string trecho = (h.size() >= static_cast<size_t>(mostrador))
                            ? h.substr(0, mostrador) : h;
        std::cout << "  " << (i + 1) << "  " << arquivos[i].nomeArquivo
                  << "  | hash começa com: " << trecho << " ...\n";
    }

    std::cout << "\nSua escolha: ";
    int opcao = pedirOpcaoValido(1, total);

    // Marca os arquivos escolhidos
    for (size_t i = 0; i < arquivos.size(); ++i) {
        if (opcao == 0 || opcao == static_cast<int>(i + 1)) {
            arquivos[i].selecionado = true;
        }
    }

    int escolhidos = 0;
    for (const auto& a : arquivos) {
        if (a.selecionado) ++escolhidos;
    }

    // ===========================================================
    // ETAPA 3 — gera o rTales.ini SÓ com os arquivos escolhidos
    // ===========================================================
    if (escolhidos > 0) {
        std::ofstream iniFile("rTales.ini");
        for (const auto& a : arquivos) {
            if (a.selecionado) {
                iniFile << "\"" << a.nomeArquivo << "\" : " << a.hash512 << "\n";
            }
        }
        iniFile.close();
        std::cout << "[3/3] Arquivo \"rTales.ini\" gerado com "
                  << escolhidos << " arquivo(s) selecionado(s).\n";
    } else {
        std::cout << "\n[Nenhum arquivo selecionado] — nenhum \"rTales.ini\" foi criado.\n";
        std::cout << "     Para criar, escolha um número acima.\n";
    }

    return 0;
}
```

**Como funciona o fluxo:**

1. O programa varre a pasta e calcula o Keccak-512 de cada `.exe/.dll/.asi`, salvando todos em **`rTalesHash.txt`**.
2. Em seguida mostra a lista numerada dos arquivos no terminal. Você digita:
   - o **número da linha** do arquivo desejado → ele vai para o `rTales.ini`;
   - `0` → nada é incluído (sem criação do `.ini`);
   - qualquer outro número → aviso de erro (o validador repete até acertar).
3. Por fim, o programa gera um novo **`rTales.ini`** contendo apenas os arquivos selecionados, no mesmo formato (`"nome" : hash`).

**Compilação (exemplos rápidos):**

- **Ubuntu/Debian/Arch:**
  ```bash
  sudo apt-get install libcrypto++-dev    # ou similar na sua distro
  g++ -std=c++17 -O2 -o tales_hash suas_fontes/tales_hash.cpp -lcrypto++
  ```
  (Em ARM64 pode ser necessário `-lcrypto++arm64`.)
- **Windows:** baixe o pacote do Cryptopp (Visual Studio) e vincule `Cryptopp.lib`; há um template oficial no repositório `cryptopp-samples` se preferir.

É só rodar o compilado apontando para a pasta que deseja varrer (ou deixando o padrão da pasta atual) que ele faz os três passos automaticamente.
